10	/**
11	 * Emits an audit trail entry, via the dedicated {@code AUDIT} logger, for a
12	 * successfully created owner. The line carries the owner id, the assigned
13	 * customerCode, the registrationDate and the assigned membershipLevel.
14	 */
15	public class AuditOwnerCreated {
16	
17	    private static final Logger audit = LoggerFactory.getLogger("AUDIT");
18	
19	    public void service(@Val Owner owner) {
20	        audit.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
21	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
