1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.util.Map;
4	
5	/**
6	 * Fixed lookups used to derive an owner's locality. The locality prefers the postcode
7	 * range and falls back to the city-to-region table; cities not in the table (and with no
8	 * postcode-derived region) derive the locality {@link #UNKNOWN}.
9	 */
10	public final class Localities {
11	
12	    /** The canonical region string returned for any city not in {@link #CITY_REGION}. */
13	    public static final String UNKNOWN = "UNKNOWN";
14	
15	    /** City -> canonical region. */
16	    private static final Map<String, String> CITY_REGION = Map.of(
17	            "Sydney", "NSW",
18	            "Melbourne", "VIC",
19	            "Brisbane", "QLD");
20	
21	    /** Region -> inclusive 4-digit postcode range {@code {low, high}}. */
22	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
23	            "NSW", new int[] {2000, 2099},
24	            "VIC", new int[] {3000, 3099},
25	            "QLD", new int[] {4000, 4099});
26	
27	    private Localities() {
28	    }
29	
30	    /**
31	     * Derive the canonical region for a city, or {@link #UNKNOWN} when the city is not
32	     * in the fixed table (including when {@code city} is null).
33	     */
34	    public static String region(String city) {
35	        return CITY_REGION.getOrDefault(city, UNKNOWN);
36	    }
37	
38	    /**
39	     * Derive the canonical region, preferring the postcode. When {@code postcode} is a
40	     * 4-digit value falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
41	     * QLD 4000-4099) that region is returned, disambiguating cities that share a name.
42	     * Otherwise (postcode absent, non-numeric, or in no known range) the fixed
43	     * city-to-region table is used, returning {@link #UNKNOWN} for an unknown city.
44	     */
45	    public static String locality(String city, String postcode) {
46	        String byPostcode = regionForPostcode(postcode);
47	        return byPostcode != null ? byPostcode : region(city);
48	    }
49	
50	    /**
51	     * The region whose range contains the given 4-digit postcode, or {@code null} when
52	     * the postcode is absent, non-numeric, or in no known range.
53	     */
54	    private static String regionForPostcode(String postcode) {
55	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
56	            return null;
57	        }
58	        int value = Integer.parseInt(postcode);
59	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
60	            int[] range = entry.getValue();
61	            if (value >= range[0] && value <= range[1]) {
62	                return entry.getKey();
63	            }
64	        }
65	        return null;
66	    }
67	
68	    /**
69	     * The inclusive {@code {low, high}} 4-digit postcode range for a region, or {@code null}
70	     * when the region is not in the fixed table (i.e. {@link #UNKNOWN}), meaning any 4-digit
71	     * postcode is acceptable.
72	     */
73	    public static int[] postcodeRange(String region) {
74	        return REGION_POSTCODES.get(region);
75	    }
76	}
