1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's numeric membership level (1 to 3) from stable owner fields,
7	 * replacing the former string membership tier.
8	 *
9	 * <p>The level starts at 1, gains 1 when the owner has an email, gains 1 when the
10	 * owner's {@code namesakeCount} is 0, and is capped at 3. Level 4 is reserved for
11	 * tenure. Because it depends only on the persisted email and namesakeCount, the
12	 * create response and any later GET compute the same value.
13	 */
14	public final class MembershipLevels {
15	
16	    /** The highest level derivable at creation; level 4 is reserved for tenure. */
17	    public static final int MAX_LEVEL = 3;
18	
19	    private MembershipLevels() {
20	    }
21	
22	    /**
23	     * Compute the membership level for the given owner.
24	     */
25	    public static int of(Owner owner) {
26	        int level = 1;
27	        String email = owner.getEmail();
28	        if (email != null && !email.isBlank()) {
29	            level++;
30	        }
31	        Integer namesakeCount = owner.getNamesakeCount();
32	        if (namesakeCount != null && namesakeCount == 0) {
33	            level++;
34	        }
35	        return Math.min(level, MAX_LEVEL);
36	    }
37	}
