8	/**
9	 * Rejects a create-owner request whose derived {@link OwnerIdentityKey} exactly matches an
10	 * existing owner's, responding 409. This is the single consolidated duplicate check, replacing
11	 * the former separate telephone, email and household checks: because the telephone is part of
12	 * the key, two members of the same household (same householdId) with different telephones have
13	 * different keys and are both allowed — only an exact full-key match is a duplicate.
14	 *
15	 * <p>Runs after {@link ValidateOwnerFields} (which normalizes the telephone to E.164 and
16	 * lower-cases the email) and before {@link BuildOwner}. The request's household is the one it
17	 * would resolve to against existing owners (see {@link OwnerHousehold#resolve}), so the key
18	 * matches the {@code householdId} later assigned by {@link AssignOwnerHousehold}.
19	 */
20	public class EnsureUniqueOwnerIdentity {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DuplicateOwnerIdentityException {
24	        String householdId = OwnerHousehold.resolve(request.getLastName(), request.getAddress(), ownerRepository);
25	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(), householdId);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
28	                throw new DuplicateOwnerIdentityException(identityKey);
29	            }
30	        }
31	    }
32	}
